#!/usr/bin/env bun

import { GenerateConfig, runGenerateCli } from "@beep/codegen-kit";

const packageRoot = `${import.meta.dirname}/..`;
const generatedHeader = `/**
 * Generated eCFR HttpApi contract. Do not edit this file by hand.
 *
 * Run \`bun run generate\` after changing \`openapi.json\`.
 *
 * @packageDocumentation
 * @since 0.0.0
 */`;

const config = GenerateConfig.make({
  packageName: "@beep/ecfr",
  name: "EcfrApi",
  identity: { composer: "$EcfrId", moduleId: "_generated/Ecfr.gen" },
  source: { _tag: "file", path: `${packageRoot}/openapi.json` },
  dialect: "swagger-2.0",
  patches: [],
  transforms: [],
  format: "httpapi",
  output: {
    path: `${packageRoot}/src/_generated/Ecfr.gen.ts`,
    header: generatedHeader,
  },
});

runGenerateCli(config);
